import { expect, expectStatus, test } from "../../fixtures";

interface VendorOut {
  id: string;
  status: string;
}

interface DocumentOut {
  id: string;
  vendor_id: string;
  kind: string;
  status: "processing" | "extracted" | "failed";
}

interface ExtractionOut {
  id: string;
  document_id: string;
  kind: string;
  fields: Record<string, { value: string | null; confidence: number }>;
}

const suffix = () => `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

test.describe("upload vendor documents", () => {
  test(
    "fields that cannot be parsed get low confidence",
    { tag: "@DOC-03" },
    async ({ apiAs }) => {
      // Arrange: signed in as a member, with a vendor in draft status.
      const member = await apiAs("member");
      const id = suffix();

      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: `Vendor ${id}`,
          category: "services",
          contact_email: `vendor-${id}@northwind.test`,
        },
      });
      const vendor = await expectStatus<VendorOut>(vendorResponse, 201);
      expect(vendor.status).toBe("draft");

      // Act: upload an insurance certificate whose expiry date is unparseable.
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: `certificate-${id}.txt`,
            mimeType: "text/plain",
            buffer: Buffer.from("Insurance certificate. Expiry date: next spring."),
          },
        },
      });
      const document = await expectStatus<DocumentOut>(uploadResponse, 201);
      expect(document.vendor_id).toBe(vendor.id);
      expect(document.kind).toBe("insurance_certificate");

      // Wait for background processing to finish.
      await expect
        .poll(
          async () => {
            const response = await member.get(`/api/documents/${document.id}`);
            return (await expectStatus<DocumentOut>(response, 200)).status;
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .toBe("extracted");

      // Assert: the expiry_date field has a null value and confidence below 0.5.
      const extractionResponse = await member.get(`/api/documents/${document.id}/extraction`);
      const extraction = await expectStatus<ExtractionOut>(extractionResponse, 200);
      expect(extraction.document_id).toBe(document.id);

      const expiry = extraction.fields["expiry_date"];
      expect(expiry).toBeDefined();
      expect(expiry.value).toBeNull();
      expect(expiry.confidence).toBeLessThan(0.5);
    },
  );
});
